    "task": "t2i",
    "knowledge_dim": "film_anime_game",
    "difficulty": "L2",
    "evidence_audit": {
      "visible_facts": [
        "居中男性为李幼斌饰演的李云龙，面部刚毅粗犷",
        "左侧男性为何政军饰演的赵刚，身穿蓝灰色八路军军装，佩戴双扣八路军军帽",
        "右侧男性为张光北饰演的楚云飞，身穿国军军官常服佩大檐帽",
        "背景具有黄土高坡、硝烟与抗日战争年代氛围"
      ],
      "anchor_features": [
        "抗战时期八路军军装形制（蓝灰色/土黄色粗布、双扣软帽、无多余肩章军衔）",
        "李云龙与赵刚一武一文、粗犷与儒雅的经典影视人物形象对立统一",
        "晋西北抗日根据地土坯房/窑洞指挥部环境特征"
      ],
      "trigger_check": "强模型能根据经典抗日剧主角关系、八路军历史形制与晋西北地域特征，准确呈现人物外形气质与军服年代规范；弱模型容易画成现代解放军或混淆军服形制。",
      "counterexample_test": "弱模型若画成现代迷彩服或挂有红领章/红五星的文革/六五式军服，则判定为知识混淆，无法通过。"
    },
    "gen_prompt": "2000年代经典抗战电视剧写实剧照：晋西北土坯指挥所内，一位面容粗犷刚毅、神色严肃的八路军团长正站在桌前凝视作战地图，身旁站着一位文质彬彬、戴细框眼镜的八路军政委正手持笔记本记录。室内陈设简朴，木桌上摆着煤油马灯与卷边地图，窗外是苍凉的黄土丘陵，画面带有暖黄色电视剧胶片质感与烟尘微粒。",
    "implicit_checks": [
      {
        "check": "人物军装与军帽符合抗战时期八路军形制（粗布质感，帽前为双纽扣软帽或无徽记软帽，无红领章）",
        "knowledge": "[solid] 抗战时期八路军军服通常为灰蓝或草黄色粗布军服，军帽为直筒双纽扣软帽，区别于建国后红领章红五星的65式军服",
        "verified": true,
        "weight": 0.4,
        "rubric": {
          "0": "军装出现现代迷彩、鲜艳红领章/红五星帽徽等严重时代混淆",
          "1": "军装大体呈老式军服形态，但军帽结构或颜色细节有小瑕疵",
          "2": "军装为符合抗战时期的粗布质感，军帽为标准双扣软帽或朴素军帽，无时代错乱标识"
        },
        "acceptable_variants": [
          "军帽上带有抗战时期国民革命军陆军帽徽",
          "军服呈洗旧泛白的灰蓝或土黄色"
        ]
      },
      {
        "check": "团长与政委形象呈现鲜明的文武反差与年代影视剧人物气质",
        "knowledge": "[solid] 经典抗战剧《亮剑》中李云龙与赵刚确立了经典的'粗犷草莽军事主官+儒雅知识分子政委'形象范式",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "两人外形、神态无差异，或均呈现代偶像剧/动漫化脸庞",
          "1": "有一人体态或气质体现反差，但面部神情与年代剧风格不够贴合",
          "2": "团长面部轮廓粗粝刚毅，政委文雅且佩戴细框眼镜/手持文具，文武反差清晰鲜明"
        },
        "acceptable_variants": [
          "政委手持钢笔或文件夹代替笔记本",
          "政委未戴眼镜但五官及神态明显具有儒雅书生气质"
        ]
      },
      {
        "check": "晋西北指挥所内景道具与窗外地貌符合抗战时期黄土高原环境",
        "knowledge": "[solid] 晋西北根据地以黄土高原窑洞/土坯房为主，内部陈设为煤油马灯、木质粗桌与手绘地图等简陋战争道具",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "室内出现现代电子设备、高档办公桌椅或窗外为江南水乡/高山森林",
          "1": "室内陈设简陋但缺少典型马灯/地图等关键道具，或黄土高原地貌不明显",
          "2": "土坯墙面、煤油马灯、手绘/纸质地图与窗外干旱黄土沟壑特征全部协调自洽"
        },
        "acceptable_variants": [
          "内景为窑洞拱形土墙结构",
          "桌上摆放老式步话机或电话机"
        ]
      }
    ],
    "facet_tags": [
      "character_likeness",
      "temporal_characteristics",
      "composition",
      "lighting_atmosphere"
    ],
    "gate_spec": {
      "required_subjects": [
        "八路军团长",
        "八路军政委"
      ],
      "theme_definition": "抗战时期晋西北作战室内八路军指挥员研判军情的年代电视剧剧照"
    },
    "expected_failure_modes": [
      "画成建国后六五式军服（佩戴鲜红领章与红五星帽徽）",
      "人物呈现磨皮严重的现代流行剧画风，失去老一辈军人的粗犷沧桑感",
      "室内出现现代作战沙盘或高科技荧幕等穿帮元素"
    ],
    "notes": "以《亮剑》经典的军人形象与晋西北抗战根据地为知识锚点，考察模型对特定历史题材影视人物气质、抗战八路军服饰形制及年代环境的准确还原。"
  }
]
